DO $$ BEGIN CREATE TYPE public.custody_event_type AS ENUM ('pickup','handover','warehouse_in','warehouse_out','transit','delivery_attempt','delivered','returned'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.freight_config_state AS ENUM ('CONFIGURED','OWNER_CONFIGURATION_REQUIRED','PROVIDER_CONFIGURATION_REQUIRED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.freight_finding_severity AS ENUM ('INFO','MINOR','MAJOR','CRITICAL'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.freight_finding_state AS ENUM ('OPEN','ACKNOWLEDGED','RESOLVED','WAIVED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.offline_command_state AS ENUM ('QUEUED','SYNCING','ACCEPTED','REJECTED','CONFLICT', 'RETRYABLE_FAILURE','PERMANENT_FAILURE','REPLAYED','ACKNOWLEDGED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.offline_device_state AS ENUM ('ACTIVE','STALE','SUSPENDED','RETIRED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.partner_api_credential_status AS ENUM ('active', 'rotating', 'revoked'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.partner_api_environment AS ENUM ('sandbox', 'production'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.readiness_evidence_state AS ENUM ('MISSING','EVIDENCE_SUBMITTED','PENDING_APPROVAL','APPROVED','REJECTED','REVISION_REQUESTED','EXPIRED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.readiness_remediation_class AS ENUM ('BUILDABLE','CONFIGURABLE','INTEGRATABLE','TESTABLE','EVIDENCE_REQUIRED', 'HUMAN_APPROVAL_REQUIRED','EXTERNAL_INFRASTRUCTURE_REQUIRED','LEGAL_DETERMINATION_REQUIRED', 'BUSINESS_TARGET_REQUIRED','GENUINE_FAILURE'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.rfq_invitation_state AS ENUM ('INVITED','VIEWED','RESPONDED','DECLINED','EXPIRED','WITHDRAWN'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.sync_session_state AS ENUM ('OPEN','COMPLETED','ABANDONED','FAILED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.trust_case_category AS ENUM ('safety','fraud','harassment','package_tamper','identity','payment','policy','other'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.trust_case_severity AS ENUM ('low','medium','high','critical'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.trust_case_status AS ENUM ('open','in_review','investigating','escalated','resolved','closed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.trust_subject_type AS ENUM ('rider','driver','corporate','courier','vehicle','package','trip','device','ip'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS public.delivery_assignment_queue ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES public.delivery_dispatch_jobs(id) ON DELETE CASCADE, driver_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, offered_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, response text, responded_at timestamptz );
CREATE TABLE IF NOT EXISTS public.delivery_document_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES public.driver_documents(id) ON DELETE CASCADE, actor_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, event_type text NOT NULL, notes text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT delivery_doc_event_type_check CHECK (event_type IN ('uploaded','resubmitted','submitted','approved','rejected','expired','deleted','note')) );
CREATE TABLE IF NOT EXISTS public.delivery_fraud_signals ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), signal_type text NOT NULL, severity text NOT NULL DEFAULT 'medium', package_id uuid, pod_id uuid, job_id uuid, details jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'open', reviewer_id uuid, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.delivery_interventions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), package_id uuid, driver_id uuid, intervention text NOT NULL, reason text, actor_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, outcome text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.delivery_onboarding ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, module text NOT NULL, step integer NOT NULL DEFAULT 0, company_name text, contact_name text, contact_email text, contact_phone text, service_area text, fleet_size integer, submitted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (user_id, module) );
CREATE TABLE IF NOT EXISTS public.email_delivery_events ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, provider TEXT NOT NULL DEFAULT 'smtp2go', event_type TEXT NOT NULL, recipient_email TEXT NOT NULL, message_id TEXT, provider_message_id TEXT, bounce_type TEXT, reason TEXT, signature_verified BOOLEAN NOT NULL DEFAULT false, source_ip TEXT, occurred_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), payload JSONB NOT NULL DEFAULT '{}'::jsonb, payload_sha256 TEXT, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), UNIQUE (provider, event_type, recipient_email, payload_sha256) );
CREATE TABLE IF NOT EXISTS public.event_consumers ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), consumer_name text NOT NULL, channel text NOT NULL, last_event_id uuid, last_event_at timestamptz, lag_ms int NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'active', tenant_id uuid, region_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (consumer_name, channel) );
CREATE TABLE IF NOT EXISTS public.event_outbox ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), aggregate text NOT NULL, aggregate_id uuid NOT NULL, event_type text NOT NULL, payload jsonb NOT NULL, dedupe_key text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'pending', attempts int NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), last_error text, processed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.freight_audit_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scope text NOT NULL DEFAULT 'window', window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, bookings_scanned integer NOT NULL DEFAULT 0, charges_scanned integer NOT NULL DEFAULT 0, invoices_scanned integer NOT NULL DEFAULT 0, findings integer NOT NULL DEFAULT 0, critical integer NOT NULL DEFAULT 0, balanced boolean NOT NULL DEFAULT true, triggered_by uuid, correlation_id uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.freight_billing_config ( key text PRIMARY KEY, label text NOT NULL, category text NOT NULL, state public.freight_config_state NOT NULL DEFAULT 'OWNER_CONFIGURATION_REQUIRED', value jsonb NOT NULL DEFAULT '{}'::jsonb, owner_role text, guidance text, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.freight_consignment_items ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), consignment_id uuid NOT NULL REFERENCES public.freight_consignments(id) ON DELETE CASCADE, item_no integer NOT NULL, description text NOT NULL, handling_unit text NOT NULL DEFAULT 'CARTON', quantity integer NOT NULL DEFAULT 1, unit_weight_kg numeric(12,3), length_cm numeric(10,2), width_cm numeric(10,2), height_cm numeric(10,2), volume_cbm numeric(12,4), declared_value numeric(14,2), hazardous boolean NOT NULL DEFAULT false, temperature_controlled boolean NOT NULL DEFAULT false, marks_and_numbers text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (consignment_id, item_no), CONSTRAINT freight_items_quantity_positive CHECK (quantity > 0), CONSTRAINT freight_items_weight_positive CHECK (unit_weight_kg IS NULL OR unit_weight_kg > 0), CONSTRAINT freight_items_handling_unit CHECK (handling_unit IN ('CARTON','PALLET','CRATE','DRUM','SACK','BUNDLE','CONTAINER','LOOSE','ENVELOPE')) );
CREATE TABLE IF NOT EXISTS public.freight_hub_receipts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), receipt_number text NOT NULL UNIQUE, hub_id uuid NOT NULL REFERENCES public.logistics_hubs(id), consignment_id uuid NOT NULL REFERENCES public.freight_consignments(id) ON DELETE CASCADE, order_id uuid, inbound_leg_id uuid REFERENCES public.logistics_order_legs(id), vehicle_id uuid, driver_id uuid, arrival_at timestamptz, received_at timestamptz NOT NULL DEFAULT now(), received_by uuid, condition text NOT NULL DEFAULT 'GOOD' CHECK (condition IN ('GOOD','DAMAGED','PARTIAL')), units_expected integer NOT NULL DEFAULT 0, units_received integer NOT NULL DEFAULT 0, weight_received_kg numeric NOT NULL DEFAULT 0, exceptions_raised integer NOT NULL DEFAULT 0, idempotency_key text UNIQUE, notes text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (hub_id, consignment_id, inbound_leg_id) );
CREATE TABLE IF NOT EXISTS public.freight_hub_sla_config ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hub_id uuid REFERENCES public.logistics_hubs(id) ON DELETE CASCADE, receiving_minutes integer NOT NULL DEFAULT 60, sort_minutes integer NOT NULL DEFAULT 120, crossdock_minutes integer NOT NULL DEFAULT 240, max_dwell_minutes integer NOT NULL DEFAULT 480, outbound_connection_minutes integer NOT NULL DEFAULT 360, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.freight_outbound_manifests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), manifest_number text NOT NULL UNIQUE, hub_id uuid NOT NULL REFERENCES public.logistics_hubs(id), next_leg_id uuid REFERENCES public.logistics_order_legs(id), route_instance_id uuid REFERENCES public.freight_route_instances(id), dispatch_request_id uuid REFERENCES public.logistics_dispatch_requests(id), vehicle_id uuid, driver_id uuid, destination_label text, status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ( 'DRAFT','VERIFYING','VERIFIED','LOAD_MISMATCH','DEPARTED','CANCELLED')), planned_units integer NOT NULL DEFAULT 0, planned_weight_kg numeric NOT NULL DEFAULT 0, planned_volume_cbm numeric NOT NULL DEFAULT 0, actual_units integer, actual_weight_kg numeric, verified_at timestamptz, verified_by uuid, departed_at timestamptz, mismatch_detail jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.freight_procurement_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_type text NOT NULL, entity_id uuid NOT NULL, action text NOT NULL, from_state text, to_state text, actor_id uuid, actor_role text NOT NULL DEFAULT 'staff', reason text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, correlation_id text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.freight_recon_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, transactions_scanned integer NOT NULL DEFAULT 0, exceptions integer NOT NULL DEFAULT 0, critical integer NOT NULL DEFAULT 0, balanced boolean NOT NULL DEFAULT true, triggered_by uuid, correlation_id uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.freight_rfq_clarifications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rfq_id uuid NOT NULL REFERENCES public.freight_rfqs(id) ON DELETE CASCADE, carrier_id uuid REFERENCES public.carrier_profiles(id) ON DELETE CASCADE, question text NOT NULL, asked_by uuid, asked_at timestamptz NOT NULL DEFAULT now(), answer text, answered_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, answered_at timestamptz, visible_to_all boolean NOT NULL DEFAULT false );
CREATE TABLE IF NOT EXISTS public.freight_rfq_invitations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rfq_id uuid NOT NULL REFERENCES public.freight_rfqs(id) ON DELETE CASCADE, carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE CASCADE, state public.rfq_invitation_state NOT NULL DEFAULT 'INVITED', match_score numeric(6,2), match_reasons jsonb NOT NULL DEFAULT '[]'::jsonb, invited_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, invited_at timestamptz NOT NULL DEFAULT now(), viewed_at timestamptz, responded_at timestamptz, declined_at timestamptz, decline_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (rfq_id, carrier_id) );
CREATE TABLE IF NOT EXISTS public.freight_rfq_lines ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rfq_id uuid NOT NULL REFERENCES public.freight_rfqs(id) ON DELETE CASCADE, line_no integer NOT NULL, description text NOT NULL, pricing_basis public.freight_pricing_basis NOT NULL DEFAULT 'PER_SHIPMENT', quantity numeric(12,3) NOT NULL DEFAULT 1 CHECK (quantity > 0), uom text NOT NULL DEFAULT 'SHIPMENT', weight_kg numeric(12,2), volume_cbm numeric(12,3), vehicle_type text, equipment text[] NOT NULL DEFAULT '{}', origin_area_code text, destination_area_code text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (rfq_id, line_no) );
CREATE TABLE IF NOT EXISTS public.governance_webhook_endpoints ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), label text NOT NULL, url text NOT NULL, secret text NOT NULL DEFAULT encode(extensions.gen_random_bytes(32),'hex'), events text[] NOT NULL DEFAULT ARRAY['alert.raised','audit.recorded','report.delivered','report.failed'], active boolean NOT NULL DEFAULT true, tolerance_seconds integer NOT NULL DEFAULT 300 CHECK (tolerance_seconds BETWEEN 30 AND 3600), description text, last_status text, last_delivered_at timestamptz, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.investigations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dispute_id uuid REFERENCES public.payment_disputes(id) ON DELETE CASCADE, assigned_to uuid, status text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','IN_PROGRESS','CLOSED')), findings text, opened_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz );
CREATE TABLE IF NOT EXISTS public.logistics_api_idempotency ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, environment public.partner_api_environment NOT NULL, idempotency_key text NOT NULL, operation text NOT NULL, request_hash text NOT NULL, state text NOT NULL DEFAULT 'in_flight' CHECK (state IN ('in_flight','completed')), response_status integer, response_body jsonb, resource_type text, resource_id uuid, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, UNIQUE (partner_id, environment, idempotency_key) );
CREATE TABLE IF NOT EXISTS public.logistics_api_rate_counters ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scope_kind text NOT NULL, scope_value text NOT NULL, environment public.partner_api_environment NOT NULL, window_start timestamptz NOT NULL, hits integer NOT NULL DEFAULT 0, UNIQUE (scope_kind, scope_value, environment, window_start) );
CREATE TABLE IF NOT EXISTS public.logistics_api_rate_limits ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scope_kind text NOT NULL CHECK (scope_kind IN ('partner','tenant','credential','endpoint','operation','default')), scope_value text NOT NULL, environment public.partner_api_environment NOT NULL DEFAULT 'production', limit_per_minute integer NOT NULL CHECK (limit_per_minute BETWEEN 1 AND 100000), burst integer NOT NULL DEFAULT 0 CHECK (burst >= 0), updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (scope_kind, scope_value, environment) );
CREATE TABLE IF NOT EXISTS public.logistics_batch_operations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operation text NOT NULL, target_activity text, idempotency_key text NOT NULL, correlation_id text NOT NULL, actor_id uuid, target_count integer NOT NULL DEFAULT 0, success_count integer NOT NULL DEFAULT 0, failure_count integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'running', reason text, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (idempotency_key) );
CREATE TABLE IF NOT EXISTS public.logistics_capacity_reservations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id uuid NOT NULL REFERENCES public.vehicles(id) ON DELETE CASCADE, driver_id uuid REFERENCES public.drivers(id), dispatch_request_id uuid NOT NULL REFERENCES public.logistics_dispatch_requests(id) ON DELETE CASCADE, capacity_reserved_kg numeric(12,2) NOT NULL, capacity_reserved_cbm numeric(12,3) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'ACTIVE', reserved_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT (now() + interval '2 hours'), released_at timestamptz, release_reason text, reserved_by uuid, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT cap_res_status CHECK (status = ANY (ARRAY['ACTIVE','CONSUMED','RELEASED','EXPIRED','INVALIDATED'])), CONSTRAINT cap_res_amount CHECK (capacity_reserved_kg > 0) );
CREATE TABLE IF NOT EXISTS public.logistics_delivery_notifications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_name text NOT NULL, package_id uuid REFERENCES public.packages(id) ON DELETE CASCADE, attempt_id uuid, return_id uuid, otp_id uuid, channel text, recipient text, status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','sent','failed','provider_configuration_required','suppressed')), provider text, provider_ref text, error_detail text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_delivery_otps ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), package_id uuid NOT NULL REFERENCES public.packages(id) ON DELETE CASCADE, attempt_id uuid REFERENCES public.logistics_delivery_attempts(id) ON DELETE SET NULL, purpose text NOT NULL DEFAULT 'delivery_confirmation' CHECK (purpose IN ('delivery_confirmation','return_handover','hub_release')), recipient_phone text, recipient_context jsonb NOT NULL DEFAULT '{}'::jsonb, code_hash text NOT NULL, code_salt text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','verified','consumed','expired','invalidated','locked')), attempts integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 5, resend_count integer NOT NULL DEFAULT 0, max_resends integer NOT NULL DEFAULT 3, expires_at timestamptz NOT NULL, verified_at timestamptz, consumed_at timestamptz, consumed_pod_id uuid, last_sent_at timestamptz, delivery_channel text, provider text, provider_message_id text, provider_status text NOT NULL DEFAULT 'not_sent', created_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_devices ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), device_id text NOT NULL, tenant_id uuid, owner_user_id uuid NOT NULL, platform text NOT NULL DEFAULT 'unknown', app_version text NOT NULL DEFAULT 'unknown', os_version text, model text, push_token text, state public.offline_device_state NOT NULL DEFAULT 'ACTIVE', state_reason text, sync_cursor bigint NOT NULL DEFAULT 0, last_seen_at timestamptz, last_sync_at timestamptz, last_clock_skew_ms integer, queued_count integer NOT NULL DEFAULT 0, failed_count integer NOT NULL DEFAULT 0, conflict_count integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT logistics_devices_unique UNIQUE (device_id, owner_user_id) );
CREATE TABLE IF NOT EXISTS public.logistics_enquiry_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), enquiry_id uuid NOT NULL REFERENCES public.logistics_enquiries(id) ON DELETE CASCADE, event_type text NOT NULL, from_status text, to_status text, note text, actor_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_event_catalogue ( event_type text PRIMARY KEY, aggregate_type text NOT NULL, event_version text NOT NULL DEFAULT 'v1', schema_version text NOT NULL DEFAULT '1.0.0', description text NOT NULL, payload_keys text[] NOT NULL DEFAULT '{}', ordinal integer NOT NULL DEFAULT 0, publishable boolean NOT NULL DEFAULT true, deprecated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_exception_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exception_id uuid NOT NULL REFERENCES public.logistics_exceptions(id) ON DELETE CASCADE, event_name text NOT NULL, from_status text, to_status text, note text, actor_id uuid, correlation_id text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_hub_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hub_id uuid NOT NULL REFERENCES public.logistics_hubs(id) ON DELETE CASCADE, action text NOT NULL CHECK (action IN ('created','updated','activated','deactivated')), actor_id uuid, before_state jsonb, after_state jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_hub_closures ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hub_id uuid NOT NULL REFERENCES public.logistics_hubs(id) ON DELETE CASCADE, closure_date date NOT NULL, reason text, closed boolean NOT NULL DEFAULT true, opens time, closes time, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (hub_id, closure_date), CONSTRAINT hub_closure_window CHECK (closed OR (opens IS NOT NULL AND closes IS NOT NULL AND closes > opens)) );
CREATE TABLE IF NOT EXISTS public.logistics_hub_contacts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hub_id uuid NOT NULL REFERENCES public.logistics_hubs(id) ON DELETE CASCADE, name text NOT NULL, contact_role text, phone text, email text, is_primary boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT hub_contact_reachable CHECK (coalesce(phone, email) IS NOT NULL) );
CREATE TABLE IF NOT EXISTS public.logistics_hub_docks ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hub_id uuid NOT NULL REFERENCES public.logistics_hubs(id) ON DELETE CASCADE, code text NOT NULL, dock_type text NOT NULL DEFAULT 'BOTH' CHECK (dock_type = ANY (ARRAY['INBOUND','OUTBOUND','BOTH'])), status text NOT NULL DEFAULT 'AVAILABLE' CHECK (status = ANY (ARRAY['AVAILABLE','OCCUPIED','BLOCKED','MAINTENANCE'])), max_vehicle_length_m numeric, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (hub_id, code) );
CREATE TABLE IF NOT EXISTS public.logistics_hub_locations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hub_id uuid NOT NULL REFERENCES public.logistics_hubs(id) ON DELETE CASCADE, zone_id uuid REFERENCES public.logistics_hub_zones(id) ON DELETE SET NULL, code text NOT NULL, location_type text NOT NULL CHECK (location_type = ANY (ARRAY['ZONE','AISLE','RACK','SHELF','BIN','STAGING_POSITION','DOCK_FLOOR'])), aisle text, rack text, shelf text, bin text, status text NOT NULL DEFAULT 'ACTIVE' CHECK (status = ANY (ARRAY['ACTIVE','BLOCKED','FULL','MAINTENANCE','QUARANTINED'])), max_units integer, max_weight_kg numeric, notes text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (hub_id, code) );
CREATE TABLE IF NOT EXISTS public.logistics_hub_operating_hours ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hub_id uuid NOT NULL REFERENCES public.logistics_hubs(id) ON DELETE CASCADE, weekday smallint NOT NULL CHECK (weekday BETWEEN 0 AND 6), opens time, closes time, closed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (hub_id, weekday), CONSTRAINT hub_hours_window CHECK (closed OR (opens IS NOT NULL AND closes IS NOT NULL AND closes > opens)) );
CREATE TABLE IF NOT EXISTS public.logistics_hub_service_areas ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hub_id uuid NOT NULL REFERENCES public.logistics_hubs(id) ON DELETE CASCADE, area_type text NOT NULL CHECK (area_type IN ('radius','polygon','city','region','corridor')), label text, city text, region text, corridor_code text, center_lat numeric(10,7), center_lng numeric(10,7), radius_km numeric, polygon jsonb, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT hub_area_radius_shape CHECK ( area_type <> 'radius' OR (center_lat IS NOT NULL AND center_lng IS NOT NULL AND radius_km IS NOT NULL AND radius_km > 0) ), CONSTRAINT hub_area_polygon_shape CHECK ( area_type <> 'polygon' OR (polygon IS NOT NULL AND jsonb_typeof(polygon) = 'array') ), CONSTRAINT hub_area_named_shape CHECK ( area_type NOT IN ('city','region','corridor') OR coalesce(city, region, corridor_code) IS NOT NULL ) );
CREATE TABLE IF NOT EXISTS public.logistics_infra_targets ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), target_role text NOT NULL CHECK (target_role IN ('staging','restore')), label text NOT NULL, endpoint_ref text NOT NULL, synthetic_fixtures_loaded boolean NOT NULL DEFAULT false, isolation_verified boolean NOT NULL DEFAULT false, verified_by uuid, verified_at timestamptz, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (target_role) );
CREATE TABLE IF NOT EXISTS public.logistics_leg_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), leg_id uuid NOT NULL REFERENCES public.logistics_order_legs(id) ON DELETE CASCADE, order_id uuid NOT NULL REFERENCES public.delivery_orders(id) ON DELETE CASCADE, event_type text NOT NULL, previous_status text, new_status text, actor_id uuid, actor_role text, hub_id uuid REFERENCES public.logistics_hubs(id), lat numeric(10,6), lng numeric(10,6), reason text, metadata jsonb NOT NULL DEFAULT '{}', dedupe_key text UNIQUE, occurred_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_leg_transitions ( from_status text NOT NULL, to_status text NOT NULL, event_name text NOT NULL, requires_reason boolean NOT NULL DEFAULT false, PRIMARY KEY (from_status, to_status) );
CREATE TABLE IF NOT EXISTS public.logistics_manifest_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), manifest_id uuid NOT NULL REFERENCES public.logistics_manifests(id) ON DELETE CASCADE, package_id uuid, event_name text NOT NULL, from_status text, to_status text, note text, actor_id uuid, correlation_id text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_manifest_lines ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), manifest_id uuid NOT NULL REFERENCES public.logistics_manifests(id) ON DELETE CASCADE, package_id uuid NOT NULL REFERENCES public.packages(id) ON DELETE CASCADE, tracking_number text NOT NULL, scan_state text NOT NULL DEFAULT 'expected' CHECK (scan_state IN ('expected','loaded','received','missing','damaged','rejected')), loaded_at timestamptz, received_at timestamptz, exception_note text, added_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (manifest_id, package_id) );
CREATE TABLE IF NOT EXISTS public.logistics_offline_command_types ( operation text PRIMARY KEY, entity_type text NOT NULL, target_rpc text NOT NULL, required_keys text[] NOT NULL DEFAULT '{}', requires_gps boolean NOT NULL DEFAULT false, offline_allowed boolean NOT NULL DEFAULT true, max_attempts integer NOT NULL DEFAULT 6, description text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_order_activities ( code text PRIMARY KEY, label text NOT NULL, description text, sequence integer NOT NULL, terminal boolean NOT NULL DEFAULT false, exception_state boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_pack_units ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hub_id uuid NOT NULL REFERENCES public.logistics_hubs(id) ON DELETE RESTRICT, package_id uuid NOT NULL REFERENCES public.packages(id) ON DELETE RESTRICT, source_package_id uuid REFERENCES public.packages(id) ON DELETE SET NULL, station_code text, packer_id uuid, packaging_type text, weight_kg numeric, length_cm integer, width_cm integer, height_cm integer, label_reference text, label_kind text CHECK (label_kind IS NULL OR label_kind = ANY (ARRAY['SHIPPING','RETURN'])), notes text, packed_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_partner_tenants ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, tenant_id uuid NOT NULL, tenant_label text, environment public.partner_api_environment NOT NULL DEFAULT 'production', scopes text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','revoked')), granted_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (partner_id, tenant_id, environment) );
CREATE TABLE IF NOT EXISTS public.logistics_pick_lists ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), pick_list_number text NOT NULL UNIQUE, hub_id uuid NOT NULL REFERENCES public.logistics_hubs(id) ON DELETE RESTRICT, order_id uuid REFERENCES public.delivery_orders(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'OPEN' CHECK (status = ANY (ARRAY['OPEN','IN_PROGRESS','COMPLETE','SHORT','CANCELLED'])), picker_id uuid, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz );
CREATE TABLE IF NOT EXISTS public.logistics_pilot_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scenario_id text NOT NULL, expected_outcome text NOT NULL, observed_outcome text NOT NULL, result text NOT NULL CHECK (result IN ('PASS','FAIL')), evidence_ref text NOT NULL, environment text NOT NULL DEFAULT 'isolated_staging', executed_by uuid, executed_at timestamptz NOT NULL DEFAULT now(), payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_pod_policies ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), offering_code text NOT NULL, version integer NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','superseded','retired')), require_signature boolean NOT NULL DEFAULT false, require_photo boolean NOT NULL DEFAULT false, require_recipient_name boolean NOT NULL DEFAULT true, require_otp boolean NOT NULL DEFAULT false, require_scan boolean NOT NULL DEFAULT false, require_geolocation boolean NOT NULL DEFAULT true, require_notes boolean NOT NULL DEFAULT false, require_id_reference boolean NOT NULL DEFAULT false, require_recipient_relationship boolean NOT NULL DEFAULT false, otp_ttl_seconds integer NOT NULL DEFAULT 600 CHECK (otp_ttl_seconds BETWEEN 60 AND 3600), otp_max_attempts integer NOT NULL DEFAULT 5 CHECK (otp_max_attempts BETWEEN 1 AND 10), otp_max_resends integer NOT NULL DEFAULT 3 CHECK (otp_max_resends BETWEEN 0 AND 10), requires_inspection_before_disposition boolean NOT NULL DEFAULT true, notes text, effective_from timestamptz, superseded_by uuid REFERENCES public.logistics_pod_policies(id), created_by uuid REFERENCES auth.users(id), activated_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (offering_code, version) );
CREATE TABLE IF NOT EXISTS public.logistics_readiness_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), control_id text NOT NULL, action text NOT NULL, from_state public.readiness_evidence_state, to_state public.readiness_evidence_state, actor uuid, actor_email text, comments text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_readiness_evidence ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), control_id text NOT NULL UNIQUE, remediation_class public.readiness_remediation_class NOT NULL, workflow_state public.readiness_evidence_state NOT NULL DEFAULT 'MISSING', owner_role text, approver_email text, evidence_ref text, document_path text, issuing_authority text, jurisdiction text, effective_at timestamptz, expiry_at timestamptz, declaration boolean NOT NULL DEFAULT false, comments text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, submitted_by uuid, submitted_at timestamptz, decided_by uuid, decided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_service_config ( offering_code text PRIMARY KEY, lifecycle text NOT NULL DEFAULT 'DRAFT', self_service_booking boolean NOT NULL DEFAULT false, enquiry_enabled boolean NOT NULL DEFAULT true, service_areas text[] NOT NULL DEFAULT '{}', operating_hours jsonb, daily_capacity_orders integer, rate_plan_id text, pricing_verified boolean NOT NULL DEFAULT false, pod_required text[] NOT NULL DEFAULT '{}', returns_policy text, claims_policy text, restricted_goods_policy text, partner_eligibility_required boolean NOT NULL DEFAULT false, compliance_status text NOT NULL DEFAULT 'NOT_ASSESSED', legal_approval_reference text, effective_from timestamptz, expires_at timestamptz, activation_authority text, last_verified_at timestamptz, notes text, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_service_config_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), offering_code text NOT NULL, action text NOT NULL, before_state jsonb, after_state jsonb, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_stop_packages ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), stop_id uuid NOT NULL REFERENCES public.logistics_route_stops(id) ON DELETE CASCADE, route_id uuid NOT NULL REFERENCES public.logistics_routes(id) ON DELETE CASCADE, route_version_id uuid NOT NULL REFERENCES public.logistics_route_versions(id) ON DELETE CASCADE, package_id uuid NOT NULL REFERENCES public.packages(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('pickup','delivery','return')), created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (route_version_id, package_id, role) );
CREATE TABLE IF NOT EXISTS public.logistics_temperature_readings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hub_id uuid REFERENCES public.logistics_hubs(id) ON DELETE CASCADE, zone_id uuid REFERENCES public.logistics_hub_zones(id) ON DELETE SET NULL, package_id uuid REFERENCES public.packages(id) ON DELETE CASCADE, reading_c numeric NOT NULL, requirement_min_c numeric, requirement_max_c numeric, excursion boolean NOT NULL DEFAULT false, evidence jsonb, exception_id uuid REFERENCES public.logistics_exceptions(id) ON DELETE SET NULL, actor_id uuid, recorded_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_webhook_endpoints ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, tenant_id uuid, environment public.partner_api_environment NOT NULL DEFAULT 'sandbox', label text NOT NULL, url text NOT NULL, api_version text NOT NULL DEFAULT 'v1', signature_version text NOT NULL DEFAULT 'v2', secret text NOT NULL, secret_fingerprint text NOT NULL, secret_rotated_at timestamptz NOT NULL DEFAULT now(), subscribed_events text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'CONFIGURED' CHECK (status IN ('CONFIGURED','ACTIVE','DEGRADED','FAILING','SUSPENDED','REVOKED')), status_reason text, max_attempts integer NOT NULL DEFAULT 8 CHECK (max_attempts BETWEEN 1 AND 20), timeout_ms integer NOT NULL DEFAULT 10000 CHECK (timeout_ms BETWEEN 1000 AND 30000), backoff_base_ms integer NOT NULL DEFAULT 2000 CHECK (backoff_base_ms BETWEEN 500 AND 60000), last_success_at timestamptz, last_failure_at timestamptz, failure_count integer NOT NULL DEFAULT 0, consecutive_failures integer NOT NULL DEFAULT 0, delivered_count integer NOT NULL DEFAULT 0, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_wh_offline_queue ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operation_key text NOT NULL UNIQUE, device_id text NOT NULL, actor_id uuid, hub_id uuid REFERENCES public.logistics_hubs(id) ON DELETE SET NULL, operation_type text NOT NULL, captured_at timestamptz NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, state text NOT NULL DEFAULT 'PENDING' CHECK (state = ANY (ARRAY['PENDING','APPLIED','DUPLICATE','CONFLICT','REJECTED'])), server_result jsonb, conflict_reason text, applied_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.package_chain_of_custody ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), package_id UUID NOT NULL, event_type public.custody_event_type NOT NULL, actor_type public.trust_subject_type, actor_id UUID, actor_label TEXT, location_lat NUMERIC(10,7), location_lng NUMERIC(10,7), location_label TEXT, signature_ref TEXT, photo_ref TEXT, seal_id TEXT, seal_intact BOOLEAN, notes TEXT, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), metadata JSONB NOT NULL DEFAULT '{}'::JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.package_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), package_id uuid NOT NULL REFERENCES public.packages(id) ON DELETE CASCADE, event_type text NOT NULL, actor_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, location_lat numeric(10,7), location_lng numeric(10,7), notes text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, occurred_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT package_event_type_check CHECK (event_type IN ('created','accepted','assigned','picked_up','loaded','in_transit','near_destination','delivered','attempted','returned','cancelled','exception','note')) );
CREATE TABLE IF NOT EXISTS public.package_returns ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), package_id uuid NOT NULL REFERENCES public.packages(id) ON DELETE CASCADE, reason text NOT NULL, initiated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'open', resolution_notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.package_tracking ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), package_id uuid NOT NULL REFERENCES public.packages(id) ON DELETE CASCADE, lat numeric(10,7) NOT NULL, lng numeric(10,7) NOT NULL, heading numeric(5,2), speed_kph numeric(5,2), accuracy_m numeric(8,2), recorded_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_api_credentials ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, environment public.partner_api_environment NOT NULL DEFAULT 'sandbox', label text NOT NULL, client_id text NOT NULL UNIQUE, secret_hash text NOT NULL, secret_fingerprint text NOT NULL, scopes text[] NOT NULL DEFAULT '{}', tier text NOT NULL DEFAULT 'integrate', status public.partner_api_credential_status NOT NULL DEFAULT 'active', rate_limit_per_min integer NOT NULL DEFAULT 2000, monthly_quota integer NOT NULL DEFAULT 500000, last_used_at timestamptz, rotated_at timestamptz, rotated_from uuid REFERENCES public.partner_api_credentials(id) ON DELETE SET NULL, grace_expires_at timestamptz, revoked_at timestamptz, revoked_by uuid, revoke_reason text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.proof_of_delivery ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), package_id uuid NOT NULL REFERENCES public.packages(id) ON DELETE CASCADE, recipient_name text, signature_url text, photo_url text, otp_verified boolean NOT NULL DEFAULT false, delivered_lat numeric(10,7), delivered_lng numeric(10,7), notes text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (package_id) );
CREATE TABLE IF NOT EXISTS public.rec_comm_documents ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.rec_comm_requests(id) ON DELETE CASCADE, document_ref text NOT NULL, verification_code text NOT NULL, storage_bucket text NOT NULL DEFAULT 'recruitment-documents', storage_path text NOT NULL, media_type text NOT NULL DEFAULT 'application/pdf', byte_size integer NOT NULL, sha256 text NOT NULL, signature text, classification text NOT NULL, watermark_text text NOT NULL, page_count integer NOT NULL DEFAULT 1, issued_at timestamptz NOT NULL DEFAULT now(), issued_by uuid, CONSTRAINT rec_comm_documents_request_once UNIQUE (request_id) );
CREATE TABLE IF NOT EXISTS public.rec_notification_jobs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid REFERENCES public.rec_applications(id) ON DELETE CASCADE, candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, transition_key text NOT NULL, channel text NOT NULL DEFAULT 'email', template_key text NOT NULL, recipient text NOT NULL, subject text, body text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, provider_message_id text, delivered_at timestamptz, last_error text, claimed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_notif_channel_chk CHECK (channel IN ('email','sms','in_app')), CONSTRAINT rec_notif_status_chk CHECK (status IN ('queued','sending','sent','delivered','failed','suppressed')), CONSTRAINT rec_notif_once UNIQUE (application_id, transition_key, channel) );
CREATE TABLE IF NOT EXISTS public.trust_cases ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), case_number TEXT NOT NULL UNIQUE DEFAULT ('TC-' || to_char(now(),'YYYYMMDD') || '-' || substr(gen_random_uuid()::text,1,8)), category public.trust_case_category NOT NULL, severity public.trust_case_severity NOT NULL DEFAULT 'medium', status public.trust_case_status NOT NULL DEFAULT 'open', subject_type public.trust_subject_type NOT NULL, subject_id UUID, title TEXT NOT NULL, summary TEXT, assigned_to UUID REFERENCES auth.users(id) ON DELETE SET NULL, sla_due_at TIMESTAMPTZ, opened_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, closed_at TIMESTAMPTZ, tags TEXT[] DEFAULT ARRAY[]::TEXT[], metadata JSONB NOT NULL DEFAULT '{}'::JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.warehouse_exports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), destination text NOT NULL, table_name text NOT NULL, exported_rows bigint, status text NOT NULL DEFAULT 'PENDING', file_url text, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, error text);
CREATE TABLE IF NOT EXISTS public.evidence_packages ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dispute_id uuid REFERENCES public.payment_disputes(id) ON DELETE CASCADE, investigation_id uuid REFERENCES public.investigations(id) ON DELETE SET NULL, kind text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, sha256 text, uploaded_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.freight_audit_findings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid REFERENCES public.freight_audit_runs(id) ON DELETE CASCADE, reason_code text NOT NULL, severity public.freight_finding_severity NOT NULL DEFAULT 'MAJOR', state public.freight_finding_state NOT NULL DEFAULT 'OPEN', booking_id uuid REFERENCES public.freight_bookings(id), award_id uuid REFERENCES public.freight_awards(id), charge_id uuid REFERENCES public.freight_charges(id), invoice_id uuid REFERENCES public.freight_invoices(id), settlement_id uuid REFERENCES public.freight_carrier_settlements(id), carrier_id uuid REFERENCES public.carrier_profiles(id), expected_amount numeric(14,2), actual_amount numeric(14,2), variance_amount numeric(14,2), currency text NOT NULL DEFAULT 'KES', detail text NOT NULL, source_records jsonb NOT NULL DEFAULT '{}'::jsonb, correlation_id uuid, owner_role text, resolution_notes text, resolution_evidence jsonb, resolved_by uuid, resolved_at timestamptz, fingerprint text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.freight_handling_units ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hu_code text NOT NULL UNIQUE, consignment_id uuid NOT NULL REFERENCES public.freight_consignments(id) ON DELETE CASCADE, item_id uuid REFERENCES public.freight_consignment_items(id) ON DELETE SET NULL, order_id uuid, seq integer NOT NULL, description text, unit_type text NOT NULL DEFAULT 'CARTON', weight_kg numeric NOT NULL DEFAULT 0 CHECK (weight_kg >= 0), volume_cbm numeric NOT NULL DEFAULT 0 CHECK (volume_cbm >= 0), status text NOT NULL DEFAULT 'PLANNED' CHECK (status IN ( 'PLANNED','IN_TRANSIT','RECEIVED','SORTED','STAGED','LOADED','DEPARTED', 'DELIVERED','MISSING','DAMAGED','HELD','TRANSFERRED')), custody_holder_type text NOT NULL DEFAULT 'CUSTOMER' CHECK ( custody_holder_type IN ('CUSTOMER','DRIVER','HUB','CARRIER','CONSIGNEE')), custody_holder_id uuid, custody_since timestamptz NOT NULL DEFAULT now(), current_hub_id uuid REFERENCES public.logistics_hubs(id), current_leg_id uuid REFERENCES public.logistics_order_legs(id), next_leg_id uuid REFERENCES public.logistics_order_legs(id), staging_zone_id uuid REFERENCES public.logistics_hub_zones(id), staging_location_id uuid REFERENCES public.logistics_hub_locations(id), arrived_at_hub_at timestamptz, received_at timestamptz, sorted_at timestamptz, staged_at timestamptz, loaded_at timestamptz, departed_hub_at timestamptz, last_scan_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (consignment_id, seq), CONSTRAINT hu_custody_singular CHECK ( NOT (custody_holder_type = 'HUB' AND status IN ('IN_TRANSIT','DEPARTED'))) );
CREATE TABLE IF NOT EXISTS public.freight_recon_exceptions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid REFERENCES public.freight_recon_runs(id) ON DELETE CASCADE, booking_id uuid REFERENCES public.freight_bookings(id), order_id uuid, carrier_id uuid REFERENCES public.carrier_profiles(id), reason_code text NOT NULL, severity public.freight_finding_severity NOT NULL DEFAULT 'MAJOR', state public.freight_finding_state NOT NULL DEFAULT 'OPEN', expected_amount numeric(14,2) NOT NULL DEFAULT 0, charged_amount numeric(14,2) NOT NULL DEFAULT 0, invoiced_amount numeric(14,2) NOT NULL DEFAULT 0, paid_amount numeric(14,2) NOT NULL DEFAULT 0, settled_amount numeric(14,2) NOT NULL DEFAULT 0, carrier_paid_amount numeric(14,2) NOT NULL DEFAULT 0, variance_amount numeric(14,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'KES', detail text NOT NULL, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, resolution_notes text, resolved_by uuid, resolved_at timestamptz, correlation_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.governance_webhook_deliveries ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), endpoint_id uuid NOT NULL REFERENCES public.governance_webhook_endpoints(id) ON DELETE CASCADE, event_type text NOT NULL, event_id text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, signature text, attempt integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'pending', response_code integer, response_body text, error text, delivered_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_api_requests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id text NOT NULL, correlation_id text NOT NULL, partner_id uuid REFERENCES public.partners(id) ON DELETE SET NULL, credential_id uuid REFERENCES public.partner_api_credentials(id) ON DELETE SET NULL, tenant_id uuid, environment public.partner_api_environment, method text NOT NULL, path text NOT NULL, operation text NOT NULL, scope_required text, outcome text NOT NULL, http_status integer NOT NULL, error_code text, latency_ms integer NOT NULL DEFAULT 0, idempotent_replay boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_batch_operation_items ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES public.logistics_batch_operations(id) ON DELETE CASCADE, order_id uuid NOT NULL, order_number text, from_activity text, to_activity text, status text NOT NULL DEFAULT 'pending', error_code text, error_detail text, attempts integer NOT NULL DEFAULT 0, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (batch_id, order_id) );
CREATE TABLE IF NOT EXISTS public.logistics_gate_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hub_id uuid NOT NULL REFERENCES public.logistics_hubs(id) ON DELETE RESTRICT, direction text NOT NULL CHECK (direction = ANY (ARRAY['ARRIVAL','DEPARTURE'])), manifest_id uuid REFERENCES public.logistics_manifests(id) ON DELETE SET NULL, carrier_id uuid REFERENCES public.carrier_profiles(id) ON DELETE SET NULL, vehicle_id uuid, driver_id uuid, vehicle_registration text, dock_id uuid REFERENCES public.logistics_hub_docks(id) ON DELETE SET NULL, seal_id text, seal_intact boolean, expected_package_count integer, declared_package_count integer, operation_key text UNIQUE, actor_id uuid, notes text, occurred_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_hub_package_stage ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hub_id uuid NOT NULL REFERENCES public.logistics_hubs(id) ON DELETE CASCADE, package_id uuid NOT NULL, stage text NOT NULL CHECK (stage IN ('received','sorted','staged','consolidated','dispatched')), inbound_manifest_id uuid REFERENCES public.logistics_manifests(id) ON DELETE SET NULL, outbound_manifest_id uuid REFERENCES public.logistics_manifests(id) ON DELETE SET NULL, custody_event_id uuid REFERENCES public.package_chain_of_custody(id) ON DELETE SET NULL, actor_id uuid, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (package_id) );
CREATE TABLE IF NOT EXISTS public.logistics_integration_events ( event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_type text NOT NULL REFERENCES public.logistics_event_catalogue(event_type), event_version text NOT NULL DEFAULT 'v1', schema_version text NOT NULL DEFAULT '1.0.0', payload_version text NOT NULL DEFAULT '1.0.0', aggregate_type text NOT NULL, aggregate_id uuid NOT NULL, sequence bigint NOT NULL, tenant_id uuid, partner_id uuid REFERENCES public.partners(id) ON DELETE SET NULL, environment public.partner_api_environment NOT NULL DEFAULT 'production', is_synthetic boolean NOT NULL DEFAULT false, occurred_at timestamptz NOT NULL DEFAULT now(), correlation_id text NOT NULL, causation_id text, actor_type text NOT NULL DEFAULT 'system', actor_id uuid, source text NOT NULL DEFAULT 'logistics', internal_reference jsonb NOT NULL DEFAULT '{}'::jsonb, payload jsonb NOT NULL DEFAULT '{}'::jsonb, dedupe_key text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (aggregate_type, aggregate_id, sequence), UNIQUE (dedupe_key) );
CREATE TABLE IF NOT EXISTS public.logistics_offline_commands ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), command_id text NOT NULL, idempotency_key text NOT NULL, device_row_id uuid NOT NULL REFERENCES public.logistics_devices(id) ON DELETE CASCADE, device_id text NOT NULL, tenant_id uuid, actor_id uuid NOT NULL, app_version text NOT NULL DEFAULT 'unknown', operation text NOT NULL, entity_type text NOT NULL, entity_id uuid, entity_version integer, sequence_number bigint NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, payload_hash text NOT NULL, gps_lat numeric, gps_lng numeric, gps_accuracy_m numeric, client_captured_at timestamptz NOT NULL, client_clock_skew_ms integer, server_received_at timestamptz, server_applied_at timestamptz, state public.offline_command_state NOT NULL DEFAULT 'QUEUED', attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz, transaction_id uuid, server_result jsonb, error_code text, error_category text, error_message text, retryable boolean, conflict_reason text, conflict_detail jsonb, resolution text, resolved_by uuid, resolved_at timestamptz, resolution_notes text, acknowledged_at timestamptz, correlation_id text NOT NULL, causation_id text, request_id text, sync_session_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT offline_commands_command_unique UNIQUE (device_id, command_id), CONSTRAINT offline_commands_idem_unique UNIQUE (actor_id, idempotency_key), CONSTRAINT offline_commands_seq_unique UNIQUE (device_row_id, sequence_number) );
CREATE TABLE IF NOT EXISTS public.logistics_order_activity_transitions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), from_code text NOT NULL REFERENCES public.logistics_order_activities(code) ON DELETE CASCADE, to_code text NOT NULL REFERENCES public.logistics_order_activities(code) ON DELETE CASCADE, actor_roles text[] NOT NULL DEFAULT ARRAY['admin','super_admin','operations_admin']::text[], required_permission text NOT NULL DEFAULT 'staff.logistics.manage', requires_reason boolean NOT NULL DEFAULT false, warning text, event_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (from_code, to_code) );
CREATE TABLE IF NOT EXISTS public.logistics_package_placement ( package_id uuid PRIMARY KEY REFERENCES public.packages(id) ON DELETE CASCADE, hub_id uuid NOT NULL REFERENCES public.logistics_hubs(id) ON DELETE RESTRICT, location_id uuid REFERENCES public.logistics_hub_locations(id) ON DELETE RESTRICT, inventory_state text NOT NULL DEFAULT 'on_hand' CHECK (inventory_state = ANY (ARRAY['on_hand','reserved','allocated','picked','packed','staged','dispatched','quarantined','hold'])), custody_holder text NOT NULL DEFAULT 'hub', merchant_owned boolean NOT NULL DEFAULT false, placed_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_pick_list_lines ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), pick_list_id uuid NOT NULL REFERENCES public.logistics_pick_lists(id) ON DELETE CASCADE, package_id uuid NOT NULL REFERENCES public.packages(id) ON DELETE RESTRICT, location_id uuid REFERENCES public.logistics_hub_locations(id) ON DELETE SET NULL, quantity_expected numeric NOT NULL DEFAULT 1, quantity_picked numeric NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'PENDING' CHECK (status = ANY (ARRAY['PENDING','PICKED','SHORT','EXCEPTION','CANCELLED'])), reason_code text, narrative text, picked_by uuid, picked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (pick_list_id, package_id) );
CREATE TABLE IF NOT EXISTS public.logistics_pod_records ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL UNIQUE REFERENCES public.logistics_delivery_attempts(id) ON DELETE RESTRICT, package_id uuid NOT NULL REFERENCES public.packages(id) ON DELETE RESTRICT, order_id uuid, policy_id uuid REFERENCES public.logistics_pod_policies(id), policy_version integer, offering_code text, status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','superseded')), recipient_name text, recipient_relationship text, recipient_id_reference text, signature_ref text, scanned_barcode text, otp_id uuid REFERENCES public.logistics_delivery_otps(id), otp_verified boolean NOT NULL DEFAULT false, captured_lat numeric, captured_lng numeric, notes text, integrity_hash text NOT NULL, captured_by uuid REFERENCES auth.users(id), captured_at timestamptz NOT NULL DEFAULT now(), supersedes_pod_id uuid REFERENCES public.logistics_pod_records(id), superseded_by_pod_id uuid REFERENCES public.logistics_pod_records(id), supersede_reason text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_return_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), return_id uuid NOT NULL REFERENCES public.package_returns(id) ON DELETE CASCADE, event_name text NOT NULL, from_status text, to_status text, note text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, actor_id uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_return_receipts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), return_id uuid NOT NULL REFERENCES public.package_returns(id) ON DELETE CASCADE, package_id uuid NOT NULL REFERENCES public.packages(id) ON DELETE CASCADE, hub_id uuid NOT NULL REFERENCES public.logistics_hubs(id), received_at timestamptz NOT NULL DEFAULT now(), received_by uuid REFERENCES auth.users(id), condition text NOT NULL CHECK (condition IN ('good','damaged','partial','unknown')), seal_state text NOT NULL DEFAULT 'unknown' CHECK (seal_state IN ('intact','broken','missing','unknown')), seal_id text, scanned_reference text, custody_event_id uuid REFERENCES public.package_chain_of_custody(id), evidence jsonb NOT NULL DEFAULT '{}'::jsonb, notes text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_sync_sessions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), device_row_id uuid NOT NULL REFERENCES public.logistics_devices(id) ON DELETE CASCADE, actor_id uuid NOT NULL, direction text NOT NULL DEFAULT 'push', state public.sync_session_state NOT NULL DEFAULT 'OPEN', cursor_before bigint NOT NULL DEFAULT 0, cursor_after bigint, commands_submitted integer NOT NULL DEFAULT 0, commands_accepted integer NOT NULL DEFAULT 0, commands_rejected integer NOT NULL DEFAULT 0, commands_conflict integer NOT NULL DEFAULT 0, commands_deferred integer NOT NULL DEFAULT 0, duplicates_suppressed integer NOT NULL DEFAULT 0, clock_skew_ms integer, connectivity text, app_version text, correlation_id text NOT NULL, request_id text, error_code text, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz );
CREATE TABLE IF NOT EXISTS public.logistics_wh_operations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operation_key text NOT NULL UNIQUE, operation_type text NOT NULL CHECK (operation_type = ANY (ARRAY[ 'GATE_ARRIVAL','GATE_DEPARTURE','RECEIVE','SCAN','SORT','STAGE','CROSS_DOCK', 'PUT_AWAY','MOVE','PICK','PACK','LABEL','CONSOLIDATE','DECONSOLIDATE', 'OUTBOUND_STAGE','DISPATCH','RETURN_RECEIVE','TEMPERATURE'])), hub_id uuid REFERENCES public.logistics_hubs(id) ON DELETE RESTRICT, package_id uuid REFERENCES public.packages(id) ON DELETE RESTRICT, order_id uuid REFERENCES public.delivery_orders(id) ON DELETE SET NULL, manifest_id uuid REFERENCES public.logistics_manifests(id) ON DELETE SET NULL, route_id uuid REFERENCES public.logistics_routes(id) ON DELETE SET NULL, stop_id uuid REFERENCES public.logistics_route_stops(id) ON DELETE SET NULL, dispatch_job_id uuid REFERENCES public.delivery_dispatch_jobs(id) ON DELETE SET NULL, return_id uuid, from_location_id uuid REFERENCES public.logistics_hub_locations(id) ON DELETE SET NULL, to_location_id uuid REFERENCES public.logistics_hub_locations(id) ON DELETE SET NULL, custody_event_id uuid REFERENCES public.package_chain_of_custody(id) ON DELETE SET NULL, from_stage text, to_stage text, quantity numeric, billable_code text, reason_code text, narrative text, device_id text, actor_id uuid, is_synthetic boolean NOT NULL DEFAULT false, payload jsonb NOT NULL DEFAULT '{}'::jsonb, occurred_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.outbox_deliveries ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES public.event_outbox(id) ON DELETE CASCADE, consumer_id uuid NOT NULL REFERENCES public.event_consumers(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'PENDING', attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), last_attempt_at timestamptz, last_status_code integer, last_error text, latency_ms integer, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (event_id, consumer_id) );
CREATE TABLE IF NOT EXISTS public.package_tamper_alerts ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), package_id UUID NOT NULL, custody_event_id UUID REFERENCES public.package_chain_of_custody(id) ON DELETE SET NULL, trust_case_id UUID REFERENCES public.trust_cases(id) ON DELETE SET NULL, alert_type TEXT NOT NULL, severity public.trust_case_severity NOT NULL DEFAULT 'high', detected_at TIMESTAMPTZ NOT NULL DEFAULT now(), detector TEXT NOT NULL DEFAULT 'system', acknowledged_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, acknowledged_at TIMESTAMPTZ, details JSONB NOT NULL DEFAULT '{}'::JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_api_webhook_deliveries ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, credential_id uuid REFERENCES public.partner_api_credentials(id) ON DELETE SET NULL, environment public.partner_api_environment NOT NULL DEFAULT 'sandbox', event_type text NOT NULL, event_id text NOT NULL, delivery_id text NOT NULL, correlation_id text NOT NULL, endpoint_url text NOT NULL, attempt integer NOT NULL DEFAULT 1, max_attempts integer NOT NULL DEFAULT 8, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'delivered', 'failed', 'dead_letter')), failure_category text CHECK (failure_category IN ( 'none', 'signature_mismatch', 'timestamp_out_of_tolerance', 'malformed_header', 'missing_header', 'duplicate_event', 'http_4xx', 'http_5xx', 'connection_error', 'timeout', 'tls_error', 'payload_rejected' )), http_status integer, response_ms integer, signature_version text NOT NULL DEFAULT 'v1', signature_valid boolean, timestamp_skew_seconds integer, payload_preview text, error_detail text, next_retry_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz, UNIQUE (delivery_id, attempt) );
CREATE TABLE IF NOT EXISTS public.rec_doc_deliveries ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid REFERENCES public.rec_comm_requests(id) ON DELETE SET NULL, document_id uuid REFERENCES public.rec_comm_documents(id) ON DELETE SET NULL, mark_id uuid, kind text NOT NULL, candidate_id uuid, application_id uuid, onboarding_case_id uuid, channel text NOT NULL DEFAULT 'email', recipient_email text NOT NULL, recipient_name text NOT NULL, requires_signature boolean NOT NULL DEFAULT false, state text NOT NULL DEFAULT 'pending' CHECK (state IN ('pending','sent','delivered','read','signed','failed')), sent_by uuid, sent_at timestamptz, provider text, provider_message_id text, delivered_at timestamptz, first_read_at timestamptz, last_read_at timestamptz, read_count integer NOT NULL DEFAULT 0, signed_at timestamptz, signed_by_name text, signature_hash text, failed_at timestamptz, failure_reason text, open_token_hash text UNIQUE, sign_token_hash text UNIQUE, token_expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_notification_deliveries ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES public.rec_notification_jobs(id) ON DELETE CASCADE, attempt integer NOT NULL, outcome text NOT NULL, provider text, provider_message_id text, error text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.freight_hub_allocations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hub_id uuid NOT NULL REFERENCES public.logistics_hubs(id), handling_unit_id uuid NOT NULL REFERENCES public.freight_handling_units(id) ON DELETE CASCADE, consignment_id uuid NOT NULL REFERENCES public.freight_consignments(id) ON DELETE CASCADE, next_leg_id uuid REFERENCES public.logistics_order_legs(id), route_instance_id uuid REFERENCES public.freight_route_instances(id), dispatch_request_id uuid REFERENCES public.logistics_dispatch_requests(id), manifest_id uuid, staging_zone_id uuid REFERENCES public.logistics_hub_zones(id), staging_location_id uuid REFERENCES public.logistics_hub_locations(id), destination_label text, status text NOT NULL DEFAULT 'ALLOCATED' CHECK (status IN ( 'ALLOCATED','STAGED','MANIFESTED','LOADED','DEPARTED','CANCELLED')), allocated_by uuid, cancelled_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.freight_hub_exceptions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exception_number text NOT NULL UNIQUE, hub_id uuid REFERENCES public.logistics_hubs(id), exception_type text NOT NULL CHECK (exception_type IN ( 'MISSING_CARGO','DAMAGED_CARGO','SHORT_RECEIPT','OVER_RECEIPT','MISROUTED_CARGO', 'WRONG_HANDLING_UNIT','WRONG_DESTINATION','TRUCK_DELAY','DOCK_CONGESTION', 'HUB_CAPACITY_EXCEEDED','SCAN_FAILURE','DOCUMENT_MISSING','UNEXPECTED_CARGO', 'MISSED_CONNECTION','DWELL_SLA_BREACH','NO_OUTBOUND_CAPACITY')), severity text NOT NULL DEFAULT 'P2' CHECK (severity IN ('P0','P1','P2','P3')), status text NOT NULL DEFAULT 'OPEN' CHECK (status IN ( 'OPEN','ACKNOWLEDGED','IN_PROGRESS','RESOLVED','CLOSED')), handling_unit_id uuid REFERENCES public.freight_handling_units(id) ON DELETE SET NULL, consignment_id uuid REFERENCES public.freight_consignments(id) ON DELETE SET NULL, order_id uuid, leg_id uuid REFERENCES public.logistics_order_legs(id), manifest_id uuid REFERENCES public.freight_outbound_manifests(id) ON DELETE SET NULL, owner_role text, owner_id uuid, detail text NOT NULL, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, raised_by uuid, acknowledged_at timestamptz, resolved_at timestamptz, resolution text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.freight_hub_scans ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scan_type text NOT NULL CHECK (scan_type IN ( 'ARRIVAL_SCAN','RECEIVING_SCAN','SORT_SCAN','STAGING_SCAN','LOAD_SCAN', 'DEPARTURE_SCAN','EXCEPTION_SCAN')), hub_id uuid NOT NULL REFERENCES public.logistics_hubs(id), handling_unit_id uuid REFERENCES public.freight_handling_units(id) ON DELETE CASCADE, consignment_id uuid REFERENCES public.freight_consignments(id) ON DELETE CASCADE, order_id uuid, leg_id uuid REFERENCES public.logistics_order_legs(id), dispatch_request_id uuid REFERENCES public.logistics_dispatch_requests(id), route_instance_id uuid REFERENCES public.freight_route_instances(id), vehicle_id uuid, driver_id uuid, actor_id uuid, device_ref text, location_label text, lat numeric, lng numeric, idempotency_key text UNIQUE, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, occurred_at timestamptz NOT NULL DEFAULT now(), received_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_offline_attachments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), command_row_id uuid REFERENCES public.logistics_offline_commands(id) ON DELETE CASCADE, device_id text NOT NULL, actor_id uuid NOT NULL, attachment_key text NOT NULL, kind text NOT NULL, content_type text, byte_size integer, sha256 text, storage_path text, state text NOT NULL DEFAULT 'QUEUED', attempts integer NOT NULL DEFAULT 0, error_code text, captured_at timestamptz NOT NULL, uploaded_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT offline_attachments_key_unique UNIQUE (device_id, attachment_key) );
CREATE TABLE IF NOT EXISTS public.logistics_offline_command_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), command_row_id uuid NOT NULL REFERENCES public.logistics_offline_commands(id) ON DELETE CASCADE, from_state public.offline_command_state, to_state public.offline_command_state NOT NULL, reason text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, actor_id uuid, actor_type text NOT NULL DEFAULT 'system', correlation_id text, occurred_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_pod_evidence_files ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), pod_id uuid NOT NULL REFERENCES public.logistics_pod_records(id) ON DELETE CASCADE, package_id uuid NOT NULL REFERENCES public.packages(id) ON DELETE CASCADE, kind text NOT NULL CHECK (kind IN ('signature','photo','id_document','scan','other')), object_ref text NOT NULL, content_hash text NOT NULL, hash_algorithm text NOT NULL DEFAULT 'sha256', byte_size bigint, mime_type text, uploaded_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_receiving_sessions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hub_id uuid NOT NULL REFERENCES public.logistics_hubs(id) ON DELETE RESTRICT, manifest_id uuid REFERENCES public.logistics_manifests(id) ON DELETE RESTRICT, gate_event_id uuid REFERENCES public.logistics_gate_events(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'OPEN' CHECK (status = ANY (ARRAY['OPEN','RECONCILED','CLOSED','ABANDONED'])), expected_count integer NOT NULL DEFAULT 0, received_count integer NOT NULL DEFAULT 0, damaged_count integer NOT NULL DEFAULT 0, variance_explained boolean NOT NULL DEFAULT false, variance_note text, operator_id uuid, opened_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_return_inspections ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), return_id uuid NOT NULL REFERENCES public.package_returns(id) ON DELETE CASCADE, receipt_id uuid REFERENCES public.logistics_return_receipts(id), package_id uuid NOT NULL REFERENCES public.packages(id) ON DELETE CASCADE, inspector_id uuid REFERENCES auth.users(id), condition text NOT NULL CHECK (condition IN ('good','damaged','partial','destroyed','unknown')), damage_found boolean NOT NULL DEFAULT false, damage_detail text, missing_contents boolean NOT NULL DEFAULT false, missing_detail text, seal_condition text NOT NULL DEFAULT 'unknown' CHECK (seal_condition IN ('intact','broken','missing','unknown')), packaging_condition text NOT NULL DEFAULT 'unknown' CHECK (packaging_condition IN ('intact','crushed','wet','torn','unknown')), photos jsonb NOT NULL DEFAULT '[]'::jsonb, notes text, completed_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_webhook_deliveries ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), endpoint_id uuid NOT NULL REFERENCES public.logistics_webhook_endpoints(id) ON DELETE CASCADE, event_id uuid NOT NULL REFERENCES public.logistics_integration_events(event_id) ON DELETE CASCADE, partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, event_type text NOT NULL, aggregate_type text NOT NULL, aggregate_id uuid NOT NULL, sequence bigint NOT NULL, environment public.partner_api_environment NOT NULL, idempotency_key text NOT NULL, request_payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','delivered','retrying','failed','dead_letter')), attempt integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 8, http_status integer, response_class text, latency_ms integer, failure_reason text, next_retry_at timestamptz NOT NULL DEFAULT now(), claimed_at timestamptz, delivered_at timestamptz, replay_of uuid REFERENCES public.logistics_webhook_deliveries(id) ON DELETE SET NULL, replayed_by uuid, correlation_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (endpoint_id, idempotency_key) );
CREATE TABLE IF NOT EXISTS public.rec_doc_delivery_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), delivery_id uuid NOT NULL REFERENCES public.rec_doc_deliveries(id) ON DELETE CASCADE, seq integer NOT NULL, event_type text NOT NULL, actor_id uuid, actor_label text NOT NULL DEFAULT 'system', client_fingerprint text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, occurred_at timestamptz NOT NULL DEFAULT now(), prev_hash text NOT NULL, hash text NOT NULL, UNIQUE (delivery_id, seq) );
CREATE TABLE IF NOT EXISTS public.freight_custody_transfers ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), handling_unit_id uuid NOT NULL REFERENCES public.freight_handling_units(id) ON DELETE CASCADE, consignment_id uuid NOT NULL REFERENCES public.freight_consignments(id) ON DELETE CASCADE, transfer_type text NOT NULL CHECK (transfer_type IN ( 'PICKUP','HUB_RECEIPT','HUB_RELEASE','DELIVERY','RECOVERY','EXCEPTION_HOLD')), from_holder_type text NOT NULL, from_holder_id uuid, to_holder_type text NOT NULL, to_holder_id uuid, hub_id uuid REFERENCES public.logistics_hubs(id), leg_id uuid REFERENCES public.logistics_order_legs(id), scan_id uuid REFERENCES public.freight_hub_scans(id), evidence_ref text, actor_id uuid, occurred_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.freight_outbound_manifest_lines ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), manifest_id uuid NOT NULL REFERENCES public.freight_outbound_manifests(id) ON DELETE CASCADE, handling_unit_id uuid NOT NULL REFERENCES public.freight_handling_units(id) ON DELETE CASCADE, allocation_id uuid REFERENCES public.freight_hub_allocations(id) ON DELETE SET NULL, consignment_id uuid, planned boolean NOT NULL DEFAULT true, loaded boolean NOT NULL DEFAULT false, load_scan_id uuid REFERENCES public.freight_hub_scans(id), discrepancy text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (manifest_id, handling_unit_id) );
CREATE TABLE IF NOT EXISTS public.logistics_return_dispositions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), return_id uuid NOT NULL REFERENCES public.package_returns(id) ON DELETE CASCADE, inspection_id uuid REFERENCES public.logistics_return_inspections(id), package_id uuid NOT NULL REFERENCES public.packages(id) ON DELETE CASCADE, disposition text NOT NULL CHECK (disposition IN ('RETURN_TO_MERCHANT','RETURN_TO_CUSTOMER','RESTOCK', 'REPAIR','REPACK','DISPOSE','HOLD','CLAIM_REVIEW')), authorized_by uuid REFERENCES auth.users(id), authorization_note text, executed_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.delivery_onboarding ADD COLUMN IF NOT EXISTS partner_type text NOT NULL DEFAULT 'courier', ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'draft', ADD COLUMN IF NOT EXISTS country text, ADD COLUMN IF NOT EXISTS city text, ADD COLUMN IF NOT EXISTS registration_number text, ADD COLUMN IF NOT EXISTS tax_pin text, ADD COLUMN IF NOT EXISTS vehicle_types text, ADD COLUMN IF NOT EXISTS monthly_volume integer, ADD COLUMN IF NOT EXISTS notes text, ADD COLUMN IF NOT EXISTS review_notes text, ADD COLUMN IF NOT EXISTS reviewed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS reviewed_at timestamptz;
ALTER TABLE public.event_consumers ADD COLUMN IF NOT EXISTS event_pattern text, ADD COLUMN IF NOT EXISTS webhook_url text, ADD COLUMN IF NOT EXISTS max_attempts integer NOT NULL DEFAULT 8, ADD COLUMN IF NOT EXISTS backoff_base_seconds integer NOT NULL DEFAULT 30, ADD COLUMN IF NOT EXISTS enabled boolean NOT NULL DEFAULT true;
ALTER TABLE public.event_outbox ADD COLUMN IF NOT EXISTS first_failed_at timestamptz, ADD COLUMN IF NOT EXISTS dead_lettered_at timestamptz;
ALTER TABLE public.event_outbox ADD COLUMN IF NOT EXISTS trace_id text, ADD COLUMN IF NOT EXISTS span_id text, ADD COLUMN IF NOT EXISTS parent_span_id text, ADD COLUMN IF NOT EXISTS idempotency_key text, ADD COLUMN IF NOT EXISTS correlation_id text, ADD COLUMN IF NOT EXISTS event_version text NOT NULL DEFAULT '1.0', ADD COLUMN IF NOT EXISTS schema_version text NOT NULL DEFAULT '1.0', ADD COLUMN IF NOT EXISTS deployment_version text, ADD COLUMN IF NOT EXISTS git_revision text, ADD COLUMN IF NOT EXISTS tenant_id uuid, ADD COLUMN IF NOT EXISTS environment text NOT NULL DEFAULT 'production', ADD COLUMN IF NOT EXISTS payment_session_id uuid, ADD COLUMN IF NOT EXISTS payment_attempt_id uuid, ADD COLUMN IF NOT EXISTS expires_at timestamptz, ADD COLUMN IF NOT EXISTS poisoned boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS error_signature text, ADD COLUMN IF NOT EXISTS delivery_latency_ms integer, ADD COLUMN IF NOT EXISTS first_attempted_at timestamptz;
ALTER TABLE public.package_returns ADD COLUMN IF NOT EXISTS return_number text, ADD COLUMN IF NOT EXISTS reason_code text, ADD COLUMN IF NOT EXISTS authorization_status text NOT NULL DEFAULT 'pending' CHECK (authorization_status IN ('pending','authorized','rejected')), ADD COLUMN IF NOT EXISTS authorized_by uuid REFERENCES auth.users(id), ADD COLUMN IF NOT EXISTS authorized_at timestamptz, ADD COLUMN IF NOT EXISTS merchant_approval_required boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS merchant_approved_by uuid REFERENCES auth.users(id), ADD COLUMN IF NOT EXISTS merchant_approved_at timestamptz, ADD COLUMN IF NOT EXISTS origin_attempt_id uuid REFERENCES public.logistics_delivery_attempts(id), ADD COLUMN IF NOT EXISTS origin_route_id uuid REFERENCES public.logistics_routes(id), ADD COLUMN IF NOT EXISTS return_route_id uuid REFERENCES public.logistics_routes(id), ADD COLUMN IF NOT EXISTS destination_hub_id uuid REFERENCES public.logistics_hubs(id), ADD COLUMN IF NOT EXISTS return_service_level text, ADD COLUMN IF NOT EXISTS return_instructions text, ADD COLUMN IF NOT EXISTS movement_status text NOT NULL DEFAULT 'AUTHORIZED' CHECK (movement_status IN ('AUTHORIZED','READY_FOR_RETURN','DISPATCHED','IN_TRANSIT', 'HUB_RECEIVED','INSPECTION','DISPOSITION','RESOLVED','CANCELLED')), ADD COLUMN IF NOT EXISTS disposition text, ADD COLUMN IF NOT EXISTS resolution_state text, ADD COLUMN IF NOT EXISTS financial_reference text, ADD COLUMN IF NOT EXISTS exception_id uuid REFERENCES public.logistics_exceptions(id), ADD COLUMN IF NOT EXISTS updated_by uuid REFERENCES auth.users(id);
ALTER TABLE public.proof_of_delivery ADD COLUMN IF NOT EXISTS image_sha256 text;
