ms','logistics_gate_events','logistics_hub_package_stage','logistics_integration_events','logistics_offline_commands','logistics_order_activity_transitions','logistics_package_placement','logistics_pick_list_lines','logistics_pod_records','logistics_return_events','logistics_return_receipts','logistics_sync_sessions','logistics_wh_operations','outbox_deliveries','package_tamper_alerts','partner_api_webhook_deliveries','rec_doc_deliveries','rec_notification_deliveries','freight_hub_allocations','freight_hub_exceptions','freight_hub_scans','logistics_offline_attachments','logistics_offline_command_events','logistics_pod_evidence_files','logistics_receiving_sessions','logistics_return_inspections','logistics_webhook_deliveries','rec_doc_delivery_events','freight_custody_transfers','freight_outbound_manifest_lines','logistics_return_dispositions'] LOOP EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t); EXECUTE format('GRANT ALL ON public.%I TO service_role', t); EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('CREATE POLICY "Admins manage restored records" ON public.%I FOR ALL TO authenticated USING (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'']::public.app_role[])) WITH CHECK (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'']::public.app_role[]))', t); END LOOP; END $$;
